-- Branded request emails: shorter template text, details generated in code.
--
-- The new-request confirmation (customer) and the new-request alert
-- (dispatch) are now sent as branded HTML emails. Every detail (request
-- number, service, published price, vehicle, location with a Maps link, the
-- dispatch checklist) is generated by src/lib/notifications/request-emails.ts
-- from the request itself. The template text below becomes the editable intro
-- paragraph, so it no longer repeats the details.
--
-- The dispatch SMS gains a Google Maps link to the pin ({{mapsUrl}}). It is
-- ASCII-only, so it stays GSM-7.
--
-- !!! APPLY ONLY AFTER THE CODE FROM THE SAME COMMIT IS DEPLOYED !!!
-- The old code sends the template body as the whole plain-text email. With
-- this shorter body it would send customers a confirmation with no tracking
-- link, and dispatch an alert with no address or phone number. The new code
-- with the old (long) body is harmless, only repetitive, so the safe order is
-- deploy first, then run this.

update notification_templates
set subject = 'We received your {{serviceName}} request — {{requestNumber}}',
    body = 'Hi {{customerName}}, thanks for choosing TRA. Your request is with our local Dallas–Fort Worth dispatch team now. Everything you sent us is below, with your live tracking link.'
where event = 'request_received' and channel = 'email';

update notification_templates
set subject = 'NEW {{serviceName}} — {{requestNumber}}{{vehicleClause}}',
    body = 'New {{serviceName}} request from {{customerName}}. Call to confirm the checklist below, then assign a driver.'
where event = 'dispatch_new_request_email' and channel = 'email';

update notification_templates
set body = 'TRA NEW {{requestNumber}}: {{serviceShort}}{{vehicleClause}}. {{customerName}} {{customerPhone}}. At {{pickupAddress}}. Map: {{mapsUrl}} Open: {{dispatchUrl}}'
where event = 'dispatch_new_request_sms' and channel = 'sms';
